import{_ as a,a0 as i,w as d,s as u,ao as l,I as p,x as e,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧-改變登陸窗口背景 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧-改變登陸窗口背景 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧-改變登陸窗口背景 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧-改變登陸窗口背景 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Daily Ubuntu Tips–Change The Logon Screen Background","title":"每日Ubuntu小技巧-改變登陸窗口背景","tag":"201311","desc":""},"relativePath":"201311/Daily Ubuntu Tips–Change The Logon Screen Background.md","filePath":"[post].md"}'),s={name:"201311/Daily Ubuntu Tips–Change The Logon Screen Background.md"};function g(m,t,b,T,c,f){const n=i("Link");return d(),u("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧-改變登陸窗口背景" tabindex="-1">每日Ubuntu小技巧-改變登陸窗口背景 <a class="header-anchor" href="#每日ubuntu小技巧-改變登陸窗口背景" aria-label="Permalink to “每日Ubuntu小技巧-改變登陸窗口背景”">​</a></h1><p>本文為你提供了一個簡單的小技巧，告訴你如何用你自己圖片來替換登陸窗口的背景。Ubuntu的登陸窗口挺不錯的，可能比大多數發行版的都要好，但是如果你想要使用一張你自己的圖片，比如一張可以讓你回憶起某個特定的地方或事情的圖片，你就可以按照下面的步驟來更換上它。</p><p>有許多方法可以做到這一點，這篇博文介紹的只是其中一種。下面介紹的方法可以使用dconf-editor和lightdm用户身份來完成這樣的效果。簡單來説就是，切換到root用户，給予lightdm用户訪問x-server的權限。然後使用lightdm用户身份，運行dconf-editor，然後做出修改。</p><p>在設置完自定義圖片並且重啓後，每次啓動電腦時你就應該能看到你設置的圖片。若設置的圖片是一張你非常喜歡的並且能給你帶給你很多回憶的圖片，那麼你每次啓動電腦登陸到Ubuntu時一定非常開心。</p><p>這個手冊假設你已經在你的電腦上安裝了dconf-editor。若沒有，你可以運行以下命令來安裝dconf-editor</p><pre><code>sudo apt-get install dconf-editor
</code></pre><p>下一步，選擇你要作為登陸背景的圖片。然後，記下圖片的位置以及圖片的名字，運行以下命令切換到root用户。</p><pre><code>sudo –i
</code></pre><p>下一步，運行以下命令給予lightdm用户訪問X-server的權限。Lightdm是一個管理登陸窗口背景的服務程序，因此假如你要更換登陸窗口的背景圖片，你就要修改lightdm用户。</p><pre><code>xhost +SI:localuser:lightdm
</code></pre><p>下一步，運行以下命令切換到lightdm用户</p><pre><code>su lightdm -s /bin/bash
</code></pre><p>然後，運行以下命令開啓dconf-editor</p><pre><code>dconf-editor
</code></pre><p>當工具打開後，瀏覽到 <strong>com-&gt;canonical-&gt;unity-greeter</strong>。然後改變背景值為自定義的圖盤。你可能需要勾掉draw-grid。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/logon-screen-background.png" alt=""></p><p>重啓電腦，盡情享受~</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/logon-screen-background-1.png" alt=""></p><hr>`,19)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tipschange-logon-screen-background/"},{default:r(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/09/daily-ubuntu-tipschange-logon-screen-background/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:r(()=>[...t[3]||(t[3]=[e("Linux中國",-1)])]),_:1}),t[6]||(t[6]=e(" 榮譽推出",-1))]),p("p",null,[t[9]||(t[9]=e("譯者：",-1)),o(n,{href:"https://github.com/Linux-pdz"},{default:r(()=>[...t[7]||(t[7]=[e("Linux-pdz",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),o(n,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...t[8]||(t[8]=[e("Caroline",-1)])]),_:1})])])}const k=a(s,[["render",g]]);export{w as __pageData,k as default};
